set -uo pipefail
cd ~/yxTPU/pretraining
export PATH=$HOME/.local/bin:$PATH PYTHONUNBUFFERED=1
export TPU_PROCESS_BOUNDS=1,1,1 TPU_CHIPS_PER_PROCESS_BOUNDS=2,2,1 TPU_VISIBLE_DEVICES=0,1,2,3
mkdir -p ~/gdn2
echo '' | base64 -d | gunzip > ~/gdn2/gdn2.patch
echo '' | base64 -d | gunzip > ~/gdn2/bench_gdn2.py
cp src/yxtpu_pretrain/kernels/kda_fused_pallas_v4.py ~/gdn2/gdn2_fused_pallas_v4.py
patch --silent ~/gdn2/gdn2_fused_pallas_v4.py < ~/gdn2/gdn2.patch && echo PATCH-OK || exit 1
rm -f /tmp/libtpu_lockfile
.venv/bin/python ~/gdn2/bench_gdn2.py 2>&1 | tail -20
echo "GDN2-BENCH-DONE"
